var APU_GROUP_BASE = [12, 8, 4, 0];
function createChBlock() {
  return {
    trackLo: 0,
    trackHi: 0,
    timingLo: 0,
    timingHi: 0,
    timingOff: 0,
    volCtrl: 0,
    apuVol: 48,
    freqLo: 0,
    freqHi: 128,
    stkPtr: 15
  };
}
function createWorkArea() {
  return {
    chMask: 0,
    durLo: new Uint8Array(NUM_CHANNELS),
    durHi: new Uint8Array(NUM_CHANNELS),
    nextDurHi: new Uint8Array(NUM_CHANNELS),
    chType: new Uint8Array(NUM_CHANNELS),
    baseFreqLo: new Uint8Array(NUM_CHANNELS),
    baseFreqHi: new Uint8Array(NUM_CHANNELS),
    seqIdx: new Uint8Array(NUM_CHANNELS),
    volDecay: new Uint8Array(NUM_CHANNELS),
    volDecayReload: new Uint8Array(NUM_CHANNELS),
    last4003: new Uint8Array(4),
    muteFlags: new Uint8Array(4),
    dmcActive: 0,
    portamentoEn: new Uint8Array(NUM_CHANNELS),
    portamentoScratch: new Uint8Array(NUM_CHANNELS),
    portamentoVal: new Int8Array(NUM_CHANNELS),
    freqDirty: new Uint8Array(NUM_CHANNELS),
    noteDur: new Uint8Array(NUM_CHANNELS),
    notePlayed: new Uint8Array(NUM_CHANNELS)
  };
}

// src/game/prg/prg-old/code/bank12_audio_engine.ts
var Bank12AudioEngine = class {
  constructor(papu) {
    this.blocks = [];
    this.w = createWorkArea();
    this.tracks = [];
    this.isPlaying = false;
    this.frameCount = 0;
    this.totalChannels = 4;
    /** one-shot mode: $FF stops channel instead of looping */
    this._oneShot = false;
    /** 音频请求槽位 ($0700-$0705, 6 个) */
    this.slots = new Uint8Array(6);
    /** Bank 12 数据源 — SE header 表与音效轨道 */
    this.seBankData = null;
    /** 标记该通道当前由 SE 占用 */
    this.seChannel = new Array(NUM_CHANNELS).fill(false);
    /** Track start positions (for restart on end-of-data) */
    this.startOffsets = [0, 0, 0, 0, 0, 0, 0, 0];
    /** Shared BGM raw data for CALL/JUMP NES address resolution */
    this.sharedData = null;
    this.bgmNesBase = 0;
    this.bgmHeaderOffset = 0;
    /** Per-channel call stack */
    this._callStacks = Array.from({ length: NUM_CHANNELS }, () => []);
    /** Per-channel loop stack */
    this._loopStacks = Array.from({ length: NUM_CHANNELS }, () => []);
    this._papu = papu;
    for (let i = 0; i < NUM_CHANNELS; i++) {
      this.blocks.push(createChBlock());
      this.tracks.push(null);
    }
  }
  /** 注入 Bank 12 SE 数据 */
  setSeBankData(data) {
    this.seBankData = new Uint8Array(data);
  }
  /**
   * $8349 — 音乐播放初始化
   * 通道映射: SQ1→ch4, SQ2→ch5, TRI→ch6, NOISE→ch7
   */
  load(trackSQ1, trackSQ2, trackTRI, trackNOISE, sharedRaw, nesBase, headerOffset) {
    this.stop();
    if (sharedRaw) {
      this.sharedData = new Uint8Array(sharedRaw);
      this.bgmNesBase = nesBase || 0;
      this.bgmHeaderOffset = headerOffset || 0;
    } else {
      this.sharedData = null;
      this.bgmNesBase = 0;
      this.bgmHeaderOffset = 0;
    }
    this.w.chMask = 0;
    if (this.sharedData) {
      let pos = this.bgmHeaderOffset || 0;
      if (this.sharedData[pos] === 255) pos += 1;
      for (let i = 0; i < 8 && pos + 2 < this.sharedData.length; i++) {
        const byte0 = this.sharedData[pos];
        if (byte0 === 255) break;
        const lo = this.sharedData[pos + 1];
        const hi = this.sharedData[pos + 2];
        pos += 3;
        const chNum = byte0;
        const nesAddr = lo | hi << 8;
        const off = this._nesAddrToOffset(nesAddr);
        const internalCh = chNum >= 4 ? chNum : chNum + 4;
        if (internalCh === 4) this._initChannel(4, trackSQ1, off);
        else if (internalCh === 5) this._initChannel(5, trackSQ2, off);
        else if (internalCh === 6) this._initChannel(6, trackTRI, off);
        else if (internalCh === 7) this._initChannel(7, trackNOISE, off);
      }
    } else {
      this._initChannel(4, trackSQ1, 0);
      this._initChannel(5, trackSQ2, 0);
      this._initChannel(6, trackTRI, 0);
      this._initChannel(7, trackNOISE, 0);
    }
    this.totalChannels = 4;
    return true;
  }
  /** $8349 init for one channel */
  _initChannel(ch, data, sharedStart = 0) {
    if (data.length === 0) return;
    const useShared = this.sharedData !== null;
    this.startOffsets[ch] = useShared ? sharedStart : 0;
    const blk = this.blocks[ch];
    blk.trackLo = useShared ? sharedStart & 255 : 0;
    blk.trackHi = useShared ? sharedStart >> 8 & 255 : 0;
    blk.timingLo = 0;
    blk.timingHi = 0;
    blk.timingOff = 0;
    blk.volCtrl = ch === 5 ? 128 : ch === 6 ? 15 : 0;
    blk.apuVol = 48;
    blk.freqLo = 0;
    blk.freqHi = 128;
    blk.stkPtr = 15;
    this.w.durLo[ch] = 1;
    this.w.durHi[ch] = 1;
    this.w.noteDur[ch] = 1;
    this.w.nextDurHi[ch] = 0;
    this.w.chType[ch] = 0;
    this.w.volDecay[ch] = 0;
    this.w.volDecayReload[ch] = 0;
    this.w.portamentoEn[ch] = 0;
    this.w.portamentoVal[ch] = 0;
    this.w.freqDirty[ch] = 0;
    this.tracks[ch] = new Uint8Array(data);
    let bit = 1;
    for (let i = 0; i < ch; i++) bit <<= 1;
    this.w.chMask |= bit;
  }
  /** 设置 one-shot 模式 */
  setOneShot(enabled) {
    this._oneShot = enabled;
  }
  /** 请求播放一个 SE 音效 */
  setSeRequest(req) {
    this.requestSlot(0, req);
  }
  /** 向指定槽位 (0-5) 写入音频请求 */
  requestSlot(idx, req) {
    if (idx < 0 || idx > 5) return;
    this.slots[idx] = req & 255;
  }
  start() {
    if (this.w.chMask === 0) return false;
    this.isPlaying = true;
    this.frameCount = 0;
    this.w.dmcActive = 0;
    for (let g = 0; g < 4; g++) {
      this.w.muteFlags[g] = 0;
      this.w.last4003[g] = 0;
    }
    this._papu.writeReg(16405, 15);
    return true;
  }
  stop() {
    this.isPlaying = false;
    this.w = createWorkArea();
    for (let i = 0; i < NUM_CHANNELS; i++) {
      this.blocks[i] = createChBlock();
      this.tracks[i] = null;
    }
    this.seChannel.fill(false);
    this.slots.fill(0);
    this.frameCount = 0;
  }
  get progress() {
    return {
      frame: this.frameCount,
      seconds: Math.round(this.frameCount / 60 * 10) / 10,
      playing: this.isPlaying
    };
  }
  // ════════════════════════════════════════════════
  // $8002 入口 — 音频请求槽位分发
  // ════════════════════════════════════════════════
  _processSlots() {
    const data = this.seBankData;
    if (!data) return;
    for (let x = 5; x >= 0; x--) {
      const val = this.slots[x];
      if (val === 0) continue;
      if (val >= 114) continue;
      if (val === 49) {
        this._slotReset();
      } else {
        this._initSe(val);
      }
      this.slots[x] = 0;
    }
  }
  /** $8070 特殊重置: 音量衰减计数器全部重载 */
  _slotReset() {
    for (let ch = 0; ch < NUM_CHANNELS; ch++) {
      const v = ch === 1 || ch === 5 ? 10 : 25;
      this.w.volDecay[ch] = v;
      this.w.volDecayReload[ch] = v;
    }
  }
  /** $8349 — SE/歌曲初始化 (来自槽位请求) */
  _initSe(req) {
    const data = this.seBankData;
    if (!data) return;
    const idx = (req - 1) * 2 & 255;
    const t = 3034 + idx;
    if (t + 1 >= data.length) return;
    const headerPtr = data[t] | data[t + 1] << 8;
    let pos = headerPtr - 32768;
    if (pos < 0 || pos >= data.length) return;
    if (data[pos] & 128) {
      this._papu.writeReg(16405, 15);
      return;
    }
    while (pos + 2 < data.length) {
      const chNum = data[pos];
      if (chNum & 128) break;
      const trackLo = data[pos + 1];
      const trackHi = data[pos + 2];
      pos += 3;
      if (chNum > 7) continue;
      const trackAddr = trackLo | trackHi << 8;
      const trackOff = trackAddr - 32768;
      if (trackOff < 0 || trackOff >= data.length) continue;
      this._initSeChannel(chNum, trackOff);
    }
  }
  /** $8349 单通道初始化 (SE 版) */
  _initSeChannel(ch, startOff) {
    const blk = this.blocks[ch];
    this.w.portamentoVal[ch] = 0;
    this.w.chType[ch] = 0;
    this.w.portamentoEn[ch] = 0;
    this.w.volDecay[ch] = 0;
    this.w.volDecayReload[ch] = 0;
    this.w.seqIdx[ch] = 0;
    this.w.freqDirty[ch] = 0;
    this.w.notePlayed[ch] = 0;
    blk.trackLo = startOff & 255;
    blk.trackHi = startOff >> 8 & 255;
    blk.timingLo = 0;
    blk.timingHi = 0;
    blk.timingOff = 0;
    blk.stkPtr = 15;
    const pm = ch & 3;
    blk.volCtrl = pm === 1 ? 128 : pm === 2 ? 15 : 0;
    blk.apuVol = 48;
    blk.freqLo = 0;
    blk.freqHi = 128;
    this.w.durLo[ch] = 1;
    this.w.durHi[ch] = 1;
    this.w.noteDur[ch] = 1;
    this.w.nextDurHi[ch] = 0;
    this.tracks[ch] = this.seBankData;
    this.startOffsets[ch] = startOff;
    this.seChannel[ch] = true;
    this._callStacks[ch] = [];
    this._loopStacks[ch] = [];
    this.w.chMask |= 1 << ch;
    this.w.last4003[2] = 0;
    this.w.last4003[3] = 0;
    this.w.dmcActive = 0;
  }
  /** Song loop restart: reinits all channels to their start offsets */
  _restartSong() {
    this.w.chMask = 0;
    for (let ch = 0; ch < NUM_CHANNELS; ch++) {
      if (this.seChannel[ch]) {
        this.seChannel[ch] = false;
        this.tracks[ch] = null;
        continue;
      }
      if (!this.tracks[ch]) continue;
      const blk = this.blocks[ch];
      const startOff = this.startOffsets[ch] || 0;
      blk.trackLo = startOff & 255;
      blk.trackHi = startOff >> 8 & 255;
      blk.timingLo = 0;
      blk.timingHi = 0;
      blk.timingOff = 0;
      blk.volCtrl = ch === 5 ? 128 : ch === 6 ? 15 : 0;
      blk.apuVol = 48;
      blk.freqLo = 0;
      blk.freqHi = 128;
      blk.stkPtr = 15;
      this.w.durLo[ch] = 1;
      this.w.durHi[ch] = 1;
      this.w.noteDur[ch] = 1;
      this.w.nextDurHi[ch] = 0;
      this.w.chType[ch] = 0;
      this.w.seqIdx[ch] = 0;
      this.w.volDecay[ch] = 0;
      this.w.volDecayReload[ch] = 0;
      this.w.portamentoEn[ch] = 0;
      this.w.portamentoVal[ch] = 0;
      this.w.freqDirty[ch] = 0;
      this.w.notePlayed[ch] = 0;
      this._callStacks[ch] = [];
      this._loopStacks[ch] = [];
      let bit = 1;
      for (let i = 0; i < ch; i++) bit <<= 1;
      this.w.chMask |= bit;
    }
    this.w.dmcActive = 0;
    for (let g = 0; g < 4; g++) {
      this.w.muteFlags[g] = 0;
      this.w.last4003[g] = 0;
    }
  }
  // ════════════════════════════════════════════════
  // 每帧更新 ($8002 入口)
  // ════════════════════════════════════════════════
  tick() {
    if (!this.isPlaying) return;
    this._processSlots();
    if (this.w.chMask === 0) {
      if (this._oneShot) {
        this.isPlaying = false;
      } else {
        this._restartSong();
      }
      return;
    }
    let mask = this.w.chMask;
    for (let ch = 0; ch < NUM_CHANNELS; ch++) {
      const chBit = 1 << ch;
      if (!(mask & chBit)) continue;
      const blk = this.blocks[ch];
      const track = this.tracks[ch];
      if (!track) continue;
      let dl = this.w.durLo[ch] - 1 & 255;
      this.w.durLo[ch] = dl;
      if (dl === 0) {
        this._sequencerTick(ch, blk, track);
      }
      let nd = this.w.durHi[ch] - 1 & 255;
      this.w.durHi[ch] = nd;
      if (nd === 0) {
        if (blk.timingHi === 255) {
          const subTable = TIMING_SUB_TABLES[blk.timingLo];
          if (subTable && subTable.length > 0) {
            let entryIdx = blk.timingOff >> 1;
            if (entryIdx >= subTable.length) entryIdx = 0;
            const [newDurLo, newNextDurHi] = subTable[entryIdx];
            nd = newDurLo;
            this.w.durHi[ch] = newDurLo;
            this.w.nextDurHi[ch] = newNextDurHi || 0;
            blk.timingOff = blk.timingOff + 2 & 255;
          } else {
            nd = this.w.durLo[ch] || 1;
            this.w.durHi[ch] = nd;
          }
        } else {
          nd = this.w.durLo[ch] || 1;
          this.w.durHi[ch] = nd;
        }
      }
      this._processVolume(ch);
    }
    const groupSlots = [
      { g: 3, mask: 17, chLow: 0, chHigh: 4 },
      { g: 2, mask: 34, chLow: 1, chHigh: 5 },
      { g: 1, mask: 68, chLow: 2, chHigh: 6 },
      { g: 0, mask: 136, chLow: 3, chHigh: 7 }
    ];
    for (const slot of groupSlots) {
      if (!(this.w.chMask & slot.mask)) continue;
      const ch = this.w.chMask & 1 << slot.chLow ? slot.chLow : slot.chHigh;
      this._writeApuReg(ch, slot.g);
    }
    let remaining = CYCLES_PER_FRAME;
    const CHUNK = 32;
    while (remaining > 0) {
      const n = remaining < CHUNK ? remaining : CHUNK;
      this._papu.clockFrameCounter(n);
      remaining -= n;
    }
    this.frameCount++;
  }
  // ════════════════════════════════════════════════
  // $83CB: 音序器 — 读取下一个音符/命令
  // ════════════════════════════════════════════════
  _sequencerTick(ch, blk, track) {
    blk.volCtrl &= 207;
    const data = this.seChannel[ch] && this.seBankData ? this.seBankData : this.sharedData || track;
    const maxLen = data.length;
    while (true) {
      const pos = blk.trackLo | blk.trackHi << 8;
      if (pos >= maxLen) {
        if (this.seChannel[ch]) {
          this.w.chMask &= ~(1 << ch);
          return;
        }
        let restartOff = this.startOffsets[ch] || 0;
        if (this.sharedData && restartOff < this.sharedData.length && this.sharedData[restartOff] === 255) {
          restartOff++;
        }
        blk.trackLo = restartOff & 255;
        blk.trackHi = restartOff >> 8 & 255;
        blk.volCtrl &= 207;
        blk.timingOff = 0;
        blk.timingLo = 0;
        blk.timingHi = 0;
        this.w.chType[ch] = 0;
        this.w.seqIdx[ch] = 0;
        this.w.portamentoEn[ch] = 0;
        this.w.portamentoVal[ch] = 0;
        this.w.notePlayed[ch] = 0;
        this._callStacks[ch] = [];
        this._loopStacks[ch] = [];
        this.w.durLo[ch] = 1;
        this.w.durHi[ch] = 1;
        this.w.noteDur[ch] = 1;
        return;
      }
      const b = data[pos];
      this._advanceTrack(blk, 1);
      if (b < 128) {
        this._parseNote(ch, blk, b);
        this.w.durLo[ch] = this.w.noteDur[ch] || 1;
        return;
      }
      if (b >= 224) {
        const ok = this._dispatchCmd(ch, blk, data, b);
        if (!ok) return;
        continue;
      }
      const durIdx = b & 63;
      const dur = DUR_TABLE[durIdx] || 1;
      this.w.durLo[ch] = dur;
      this.w.noteDur[ch] = dur;
    }
  }
  // ════════════════════════════════════════════════
  // $8404-$848D: 音符频率计算
  // ════════════════════════════════════════════════
  /**
   * $8404-$84A3 音符解析 + $84A6 公共尾部
   *
   * 直通通道 (ch==3 TRI / ch==7 NOISE): noteByte 直接作频率低字节 ($8426/$842A)。
   * 半音通道: 低 4 位 = 半音 (FREQ_TABLE), 高 4 位 = 八度 (右移 $8455-$845A)。
   * $8435 休止: volCtrl |= $20。
   * $845C-$84A3 滑音: 非零 portamentoVal → 减 portamentoScratch; 否则加。
   */
  _parseNote(ch, blk, noteByte) {
    const isDirect = ch === 3 || ch === 7;
    let fLo;
    let fHi;
    if (isDirect) {
      if (noteByte === 16) {
        blk.volCtrl |= 32;
        this._noteTail(ch);
        return;
      }
      fLo = noteByte;
      fHi = 0;
    } else {
      const semitone = noteByte & 15;
      if (semitone >= 12) {
        blk.volCtrl |= 32;
        this._noteTail(ch);
        return;
      }
      let period = FREQ_TABLE[semitone];
      fLo = period & 255;
      fHi = period >> 8 & 7;
      const octave = (noteByte & 240) >> 4;
      for (let o = 0; o < octave; o++) {
        const carry = fHi & 1;
        fHi >>= 1;
        fLo = fLo >> 1 | carry << 7;
        fHi &= 7;
      }
      if (fLo < 2 && fHi === 0) fLo = 2;
    }
    const pVal = this.w.portamentoVal[ch];
    const scratch = this.w.portamentoScratch[ch];
    if (pVal !== 0) {
      const res = fLo - scratch;
      if (res >= 0) {
        fLo = res;
      } else {
        fLo = res & 255;
        fHi = fHi - 1 & 255;
      }
    } else {
      const res = fLo + scratch;
      fLo = res & 255;
      fHi = fHi + (res > 255 ? 1 : 0) & 255;
    }
    fHi |= 128;
    this.w.baseFreqLo[ch] = fLo;
    this.w.baseFreqHi[ch] = fHi;
    blk.freqLo = fLo;
    blk.freqHi = fHi;
    this.w.freqDirty[ch] = 255;
    this.w.notePlayed[ch] = 1;
    this._noteTail(ch);
  }
  /** $84A6-$84C8 公共尾部: 清 portamentoVal, 必要时重置 timing */
  _noteTail(ch) {
    this.w.portamentoVal[ch] = 0;
    if (this.w.portamentoEn[ch] === 0) {
      this.w.durHi[ch] = 1;
      this.blocks[ch].timingOff = 0;
    }
  }
  // ════════════════════════════════════════════════
  // $84C9: 命令分发 ($E0-$FF)
  // ════════════════════════════════════════════════
  _dispatchCmd(ch, blk, data, cmdByte) {
    const read = () => {
      const pos = blk.trackLo | blk.trackHi << 8;
      if (pos < data.length) {
        this._advanceTrack(blk, 1);
        return data[pos];
      }
      return 0;
    };
    const cmdIdx = cmdByte & 31;
    switch (cmdIdx) {
      // $E0 → SET_TIMING_TABLE_PTR
      case 0: {
        const tblIdx = read();
        blk.timingLo = tblIdx;
        blk.timingHi = 255;
        blk.timingOff = 0;
        const subTable = TIMING_SUB_TABLES[tblIdx];
        if (subTable && subTable.length > 0) {
          this.w.nextDurHi[ch] = subTable[0][1] || 0;
        }
        return true;
      }
      // $E1: NOP
      case 1:
        return true;
      // $E2 → SET_VOLUME_ENV
      case 2: {
        const param = read();
        blk.volCtrl = blk.volCtrl & 240 | param & 15;
        return true;
      }
      // $E3 → OR_VOLUME_CTRL
      case 3: {
        const param = read();
        if (this.w.dmcActive === 0) {
          blk.volCtrl |= param;
        }
        return true;
      }
      // $E4 → ENABLE_SWEEP
      case 4: {
        const param = read();
        blk.volCtrl |= 16;
        const apuX = (7 - ch) * 4 & 15;
        if (apuX < 8) {
          this._papu.writeReg(16385 + apuX, param);
        }
        const grp = ch & 3;
        this.w.muteFlags[grp] = 0;
        return true;
      }
      // $E5 → SET_PORTAMENTO_AMOUNT
      // $8670: A=param; ASL; if !bit7 → $07F4,X = param<<1 (portamentoVal);
      //        LSR; $07A7,X = param (portamentoScratch, 音符解析加减量)
      case 5: {
        const param = read();
        if (!(param & 128)) {
          this.w.portamentoVal[ch] = param << 1 & 255;
        }
        this.w.portamentoScratch[ch] = param;
        return true;
      }
      // $E6, $E7: NOP
      case 6:
      case 7:
        return true;
      // $E8 → JUMP
      case 8: {
        const lo = read();
        const hi = read();
        const nesAddr = lo | hi << 8;
        const target = this.seChannel[ch] ? nesAddr - 32768 : this._nesAddrToOffset(nesAddr);
        blk.trackLo = target & 255;
        blk.trackHi = target >> 8 & 255;
        return true;
      }
      // $E9 → CALL
      case 9: {
        const lo = read();
        const hi = read();
        const nesAddr = lo | hi << 8;
        const target = this.seChannel[ch] ? nesAddr - 32768 : this._nesAddrToOffset(nesAddr);
        this._pushReturn(blk);
        blk.trackLo = target & 255;
        blk.trackHi = target >> 8 & 255;
        return true;
      }
      // $EA → RETURN
      case 10: {
        const addr = this._popReturn(blk);
        if (addr !== null) {
          blk.trackLo = addr & 255;
          blk.trackHi = addr >> 8 & 255;
        } else {
          this.w.durLo[ch] = 1;
        }
        return true;
      }
      // $EB → LOOP_START
      case 11: {
        const count = read();
        this._pushLoop(blk, count);
        return true;
      }
      // $EC → LOOP_END
      case 12: {
        const result = this._popLoop(blk);
        if (result !== null) {
          blk.trackLo = result & 255;
          blk.trackHi = result >> 8 & 255;
        }
        return true;
      }
      // $ED → SET_CHANNEL_TYPE
      case 13: {
        const param = read();
        this.w.chType[ch] = param;
        this.w.seqIdx[ch] = 0;
        return true;
      }
      // $EE: NOP
      case 14:
        return true;
      // $EF → CLEAR_CHANNEL_TYPE
      case 15: {
        this.w.chType[ch] = 0;
        return true;
      }
      // $F0, $F1: NOP
      case 16:
      case 17:
        return true;
      // $F2 → STOP ALL: NOP
      case 18:
        return true;
      // $F3 → PORTAMENTO ON
      case 19: {
        this.w.portamentoEn[ch] = 15;
        return true;
      }
      // $F4 → PORTAMENTO OFF
      case 20: {
        this.w.portamentoEn[ch] = 0;
        return true;
      }
      // $F5-$F8: NOP
      case 21:
      case 22:
      case 23:
      case 24:
        return true;
      // $F9 → DMC init A
      case 25: {
        this._dmcInit(0, 12);
        return true;
      }
      // $FA → DMC init B
      case 26: {
        this._dmcInit(3, 32);
        return true;
      }
      // $FB → DMC init C
      case 27: {
        this._dmcInit(11, 19);
        return true;
      }
      // $FC/$FD: NOP
      case 28:
      case 29:
        return true;
      // $FE → SET_VOL_DECAY ($86F6): 读 1 参数, 写 $07CF/$07D7 (volDecay/volDecayReload)
      // asm: LDA ($F4),Y; INY; STY $F6; LDX $F3; DEX; STA $07CF,X; STA $07D7,X; LDY $F6; RTS
      case 30: {
        const decay = read();
        this.w.volDecay[ch] = decay;
        this.w.volDecayReload[ch] = decay;
        return true;
      }
      // $FF → STOP CHANNEL
      case 31: {
        if (this._oneShot || this.seChannel[ch]) {
          this.w.chMask &= ~(1 << ch);
          return false;
        }
        let restartOff = this.startOffsets[ch] || 0;
        if (this.sharedData && restartOff < this.sharedData.length && this.sharedData[restartOff] === 255) {
          restartOff++;
        }
        blk.trackLo = restartOff & 255;
        blk.trackHi = restartOff >> 8 & 255;
        blk.timingLo = 0;
        blk.timingHi = 0;
        blk.timingOff = 0;
        blk.volCtrl = ch === 5 ? 128 : ch === 6 ? 15 : 0;
        blk.apuVol = 48;
        blk.freqLo = 0;
        blk.freqHi = 128;
        blk.stkPtr = 15;
        this.w.durLo[ch] = 1;
        this.w.durHi[ch] = 1;
        this.w.noteDur[ch] = 1;
        this.w.nextDurHi[ch] = 0;
        this.w.chType[ch] = 0;
        this.w.seqIdx[ch] = 0;
        this.w.volDecay[ch] = 0;
        this.w.volDecayReload[ch] = 0;
        this.w.portamentoEn[ch] = 0;
        this.w.portamentoVal[ch] = 0;
        this.w.freqDirty[ch] = 0;
        this.w.notePlayed[ch] = 0;
        this._callStacks[ch] = [];
        this._loopStacks[ch] = [];
        return false;
      }
    }
    return true;
  }
  // ════════════════════════════════════════════════
  // $81DB: 音量/包络处理
  // ════════════════════════════════════════════════
  _processVolume(ch) {
    const blk = this.blocks[ch];
    const volByte = blk.volCtrl;
    const hiNib = volByte & 240;
    let vol;
    if (hiNib & 32) {
      vol = 15;
    } else {
      vol = volByte & 15;
    }
    let vc = this.w.volDecay[ch];
    if (vc !== 0) {
      vc--;
      this.w.volDecay[ch] = vc;
      if (vc === 0) {
        vol++;
        if (vol > 15) {
          vol = 15;
          this.w.volDecayReload[ch] = 0;
          this.w.dmcActive = 128;
        }
        blk.volCtrl = hiNib | vol;
      }
      vc = this.w.volDecay[ch];
      if (vc === 0 && this.w.volDecayReload[ch] !== 0) {
        this.w.volDecay[ch] = this.w.volDecayReload[ch];
      }
    }
    const nxtDurHi = this.w.nextDurHi[ch];
    let finalVol = nxtDurHi - vol;
    if (finalVol < 0) finalVol = 0;
    finalVol |= hiNib;
    blk.apuVol = finalVol;
    const cht = this.w.chType[ch];
    if (cht === 1) {
      this._applyFreqModType1(ch);
    } else if (cht === 2) {
      this._applyFreqModType2(ch);
    }
    const apuX = (7 - ch) * 4 & 15;
    if (apuX !== 4 && this.w.notePlayed[ch]) {
      blk.freqHi |= 128;
      this.w.freqDirty[ch] = 255;
    }
  }
  // $8257-$82B3: 频率修改 (type=1)
  _applyFreqModType1(ch) {
    const blk = this.blocks[ch];
    let si = this.w.seqIdx[ch];
    if (si >= SEQ_MOD_TABLE_TYPE1.length) si = 0;
    if (this.w.notePlayed[ch]) {
      const [dLo, dHi] = SEQ_MOD_TABLE_TYPE1[si];
      let fLo = this.w.baseFreqLo[ch] + dLo & 255;
      let fHi = this.w.baseFreqHi[ch] + dHi & 7;
      if (fLo > 255) {
        fHi++;
        fLo &= 255;
      }
      blk.freqLo = fLo;
      blk.freqHi = fHi | 128;
      this.w.freqDirty[ch] = 255;
    }
    si = (si + 1) % SEQ_MOD_TABLE_TYPE1.length;
    this.w.seqIdx[ch] = si;
  }
  // $82D2-$8348: 频率修改 (type=2)
  _applyFreqModType2(ch) {
    const blk = this.blocks[ch];
    let si = this.w.seqIdx[ch];
    if (si >= SEQ_MOD_TABLE_TYPE2.length) si = 0;
    if (this.w.notePlayed[ch]) {
      const [dLo, dHi] = SEQ_MOD_TABLE_TYPE2[si];
      let fLo = this.w.baseFreqLo[ch];
      let fHi = this.w.baseFreqHi[ch] & 7;
      if (dHi < 0 || dLo < 0) {
        const val = -dLo & 255 | (dHi < 0 ? -dHi : 0) << 8;
        let period = fLo | fHi << 8;
        period -= val;
        if (period < 2) period = 2;
        fLo = period & 255;
        fHi = period >> 8 & 7;
      } else {
        fLo = fLo + dLo & 255;
        fHi = fHi + dHi & 7;
        if (fLo > 255) {
          fHi++;
          fLo &= 255;
        }
      }
      blk.freqLo = fLo;
      blk.freqHi = fHi | 128;
      this.w.freqDirty[ch] = 255;
    }
    si = (si + 1) % SEQ_MOD_TABLE_TYPE2.length;
    this.w.seqIdx[ch] = si;
  }
  // ════════════════════════════════════════════════
  // $816E: APU 寄存器写入
  // ════════════════════════════════════════════════
  _writeApuReg(ch, group) {
    const blk = this.blocks[ch];
    const isTri = group === 1;
    const apuBase = APU_GROUP_BASE[group];
    const apuAddr = 16384 + apuBase;
    const volByte = isTri ? blk.volCtrl : blk.apuVol;
    if (isTri) {
      this._papu.writeReg(apuAddr, volByte & 15 | 128);
    } else {
      this._papu.writeReg(apuAddr, volByte | 48);
    }
    if (!(blk.volCtrl & 16)) {
      this.w.muteFlags[group] = 8;
      if (apuBase < 8 || group === 0) {
        this._papu.writeReg(apuAddr + 1, 8);
      }
    }
    const sweepEnabled = (blk.volCtrl & 16) !== 0;
    if (!sweepEnabled) {
      this._papu.writeReg(apuAddr + 2, blk.freqLo);
      const fhLen2 = blk.freqHi | 24;
      if (group >= 2 && fhLen2 === this.w.last4003[group]) {
        return;
      }
      this._papu.writeReg(apuAddr + 3, fhLen2);
      this.w.last4003[group] = fhLen2;
      if (this.w.muteFlags[group] === 0) {
        this.w.last4003[group] = 0;
      }
      return;
    }
    if (!(blk.freqHi & 128)) {
      return;
    }
    blk.freqHi &= 127;
    this.w.freqDirty[ch] = 0;
    this._papu.writeReg(apuAddr + 2, blk.freqLo);
    const fh = blk.freqHi & 7;
    const fhLen = fh | 24;
    if (group >= 2 && fhLen === this.w.last4003[group]) {
      return;
    }
    this._papu.writeReg(apuAddr + 3, fhLen);
    this.w.last4003[group] = fhLen;
    if (this.w.muteFlags[group] === 0) {
      this.w.last4003[group] = 0;
    }
  }
  // ════════════════════════════════════════════════
  // DMC helpers
  // ════════════════════════════════════════════════
  _dmcInit(sampleAddr, sampleLen) {
    this._papu.writeReg(16405, 15);
    if (this.w.dmcActive === 0) {
      this._papu.writeReg(16400, 15);
      this._papu.writeReg(16402, sampleAddr);
      this._papu.writeReg(16403, sampleLen);
      this._papu.writeReg(16405, 31);
    }
  }
  // ════════════════════════════════════════════════
  // Call/Loop stack helpers
  // ════════════════════════════════════════════════
  _pushReturn(blk) {
    const ch = this.blocks.indexOf(blk);
    if (ch < 0) return;
    const addr = blk.trackLo | blk.trackHi << 8;
    if (this._callStacks[ch].length < 8) {
      this._callStacks[ch].push(addr);
    }
  }
  _popReturn(blk) {
    const ch = this.blocks.indexOf(blk);
    if (ch < 0) return null;
    const stk = this._callStacks[ch];
    if (stk.length === 0) return null;
    return stk.pop();
  }
  _pushLoop(blk, count) {
    const ch = this.blocks.indexOf(blk);
    if (ch < 0) return;
    const addr = blk.trackLo | blk.trackHi << 8;
    if (this._loopStacks[ch].length < 8) {
      this._loopStacks[ch].push({ count, addr });
    }
  }
  _popLoop(blk) {
    const ch = this.blocks.indexOf(blk);
    if (ch < 0) return null;
    const stk = this._loopStacks[ch];
    if (stk.length === 0) return null;
    const frame = stk[stk.length - 1];
    frame.count--;
    if (frame.count > 0) {
      return frame.addr;
    } else {
      stk.pop();
      return null;
    }
  }
  // ════════════════════════════════════════════════
  // Track pointer helpers
  // ════════════════════════════════════════════════
  _advanceTrack(blk, n) {
    let addr = blk.trackLo | blk.trackHi << 8;
    addr += n;
    blk.trackLo = addr & 255;
    blk.trackHi = addr >> 8 & 255;
  }
  _nesAddrToOffset(nesAddr) {
    if (this.sharedData) {
      const offset = nesAddr - this.bgmNesBase & 65535;
      if (offset < this.sharedData.length) return offset;
    }
    return nesAddr;
  }
};

