var BGM_BY_BANK = {};
for (const e of BGM_SID_LIST) {
  if (!BGM_BY_BANK[e.bank]) BGM_BY_BANK[e.bank] = [];
  BGM_BY_BANK[e.bank].push(e);
}
var BGM_BY_TYPE = {};
for (const e of BGM_SID_LIST) {
  if (!BGM_BY_TYPE[e.type]) BGM_BY_TYPE[e.type] = [];
  BGM_BY_TYPE[e.type].push(e);
}
var BGM_TOTAL_COUNT = BGM_SID_LIST.length;

// scripts/render_old_wav.ts
function writeWav(samples, sampleRate, outPath) {
  const buf = Buffer.alloc(44 + samples.length * 2);
  buf.write("RIFF", 0);
  buf.writeUInt32LE(36 + samples.length * 2, 4);
  buf.write("WAVE", 8);
  buf.write("fmt ", 12);
  buf.writeUInt32LE(16, 16);
  buf.writeUInt16LE(1, 20);
  buf.writeUInt16LE(1, 22);
  buf.writeUInt32LE(sampleRate, 24);
  buf.writeUInt32LE(sampleRate * 2, 28);
  buf.writeUInt16LE(2, 32);
  buf.writeUInt16LE(16, 34);
  buf.write("data", 36);
  buf.writeUInt32LE(samples.length * 2, 40);
  for (let i = 0; i < samples.length; i++) {
    const v = Math.max(-32768, Math.min(32767, Math.round(samples[i] * 32767)));
    buf.writeInt16LE(v, 44 + i * 2);
  }
  fs.writeFileSync(outPath, buf);
}
function renderSong(trackIdx2, durationSec) {
  const sampleRate = 44100;
  const track = BGM_SID_LIST[trackIdx2];
  if (!track) {
    console.error("\u627E\u4E0D\u5230\u8F68\u9053:", trackIdx2);
    return [];
  }
  if (track.silent) {
    console.log("  \u9759\u97F3\u8F68\u9053");
    return [];
  }
  const samples = [];
  const nes = {
    opts: {
      sampleRate,
      onAudioSample: (l, r) => samples.push((l + r) / 2)
    }
  };
  const papu = new papu_default(nes);
  const engine = new Bank12AudioEngine(papu);
  engine.load(
    track.trackSQ1 || [],
    track.trackSQ2 || [],
    track.trackTRI || [],
    track.trackNOISE || [],
    track.raw,
    track.nesBase,
    track.headerOffset
  );
  engine.start();
  const totalFrames = Math.ceil(durationSec * 60);
  for (let f = 0; f < totalFrames; f++) {
    engine.tick();
  }
  return samples;
}
var trackIdx = parseInt(process.argv[2] || "0") - 1;
var duration = parseInt(process.argv[3] || "60");
var all = process.argv[4] === "all";
var outDir = path.join(__dirname, "..", "output");
fs.mkdirSync(outDir, { recursive: true });
if (all) {
  for (let i = 0; i < BGM_SID_LIST.length; i++) {
    const outFile = path.join(outDir, `old-song-${String(i + 1).padStart(3, "0")}.wav`);
    if (fs.existsSync(outFile)) {
      console.log(`\u8DF3\u8FC7 ${i + 1}`);
      continue;
    }
    console.log(`[${i + 1}/${BGM_SID_LIST.length}] ${BGM_SID_LIST[i]?.id || "?"}...`);
    try {
      const samples = renderSong(i, duration);
      if (samples.length > 0) {
        writeWav(samples, 44100, outFile);
        console.log(`  \u5B8C\u6210: ${samples.length} \u91C7\u6837`);
      } else {
        console.log(`  \u65E0\u91C7\u6837`);
      }
    } catch (e) {
      console.error(`  \u5931\u8D25: ${e.message}`);
    }
  }
} else {
  console.log(`\u6E32\u67D3\u7B2C ${trackIdx + 1} \u9996 (${duration}\u79D2)...`);
  const samples = renderSong(trackIdx, duration);
  const outFile = path.join(outDir, `old-song-${String(trackIdx + 1).padStart(3, "0")}.wav`);
  if (samples.length > 0) {
    writeWav(samples, 44100, outFile);
    console.log(`\u5B8C\u6210: ${outFile} (${samples.length} \u91C7\u6837)`);
  } else {
    console.log("\u65E0\u91C7\u6837\u8F93\u51FA");
  }
}
